#[derive(Debug)]
struct Rec { name: String, hdr: u64, size: u64, body: u64 }

fn read_idx(path: &str) -> Result<Vec<Rec>, i32> {
    let raw = std::fs::read(path).map_err(|_| 1)?;
    if raw.len() < 9 || &raw[..5] != b"SILT1" { return Err(1); }
    let n = u32::from_le_bytes(raw[5..9].try_into().map_err(|_| 1)?) as usize;
    let mut i = 9usize;
    let mut out = Vec::with_capacity(n);
    for _ in 0..n {
        if i.checked_add(26).ok_or(1)? > raw.len() { return Err(1); }
        let hdr = u64::from_le_bytes(raw[i..i+8].try_into().map_err(|_| 1)?); i += 8;
        let size = u64::from_le_bytes(raw[i..i+8].try_into().map_err(|_| 1)?); i += 8;
        let body = u64::from_le_bytes(raw[i..i+8].try_into().map_err(|_| 1)?); i += 8;
        let nl = u16::from_le_bytes(raw[i..i+2].try_into().map_err(|_| 1)?) as usize; i += 2;
        let end = i.checked_add(nl).ok_or(1)?;
        if end > raw.len() { return Err(1); }
        let name = std::str::from_utf8(&raw[i..end]).map_err(|_| 1)?.to_string(); i = end;
        out.push(Rec { name, hdr, size, body });
    }
    if i != raw.len() { return Err(1); }
    Ok(out)
}

fn digest(text: &str) -> Result<String, i32> {
    use std::io::Write;
    let mut child = std::process::Command::new("python3")
        .args(["-c", "import hashlib,sys; print(hashlib.sha256(sys.stdin.buffer.read()).hexdigest())"])
        .stdin(std::process::Stdio::piped()).stdout(std::process::Stdio::piped())
        .spawn().map_err(|_| 1)?;
    child.stdin.as_mut().ok_or(1)?.write_all(text.as_bytes()).map_err(|_| 1)?;
    drop(child.stdin.take());
    let output = child.wait_with_output().map_err(|_| 1)?;
    if !output.status.success() { return Err(1); }
    let s = std::str::from_utf8(&output.stdout).map_err(|_| 1)?.trim().to_string();
    if s.len() != 64 || !s.bytes().all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b)) { return Err(1); }
    Ok(s)
}

#[path = "../cfgbag/kv.rs"] mod kv;
#[path = "../cfgbag/alias.rs"] mod alias;
#[path = "../ustarwalk/hdr.rs"] mod hdr;

pub fn rib_b(a: &str, b: &str) -> Result<Pack, i32> {
    let root = std::fs::canonicalize("/app/sealwell").map_err(|_| 1)?;
    let archive = std::fs::canonicalize(a).map_err(|_| 1)?;
    if !archive.starts_with(&root) || archive == root || !archive.is_file() { return Err(1); }
    let recs = read_idx(b)?;
    let scanned = hdr::scan(archive.to_str().ok_or(1)?)?;
    let regs: Vec<&hdr::Row> = scanned.iter().filter(|r| r.flag == b'0' || r.flag == 0).collect();
    if regs.len() != recs.len() { return Err(1); }
    for (r, h) in recs.iter().zip(regs.iter()) {
        if r.name != h.name || r.hdr != h.hdr || r.size != h.size || r.body != h.body { return Err(1); }
    }

    let mut timezone = String::new();
    let mut cluster = String::new();
    let mut events = Vec::new();
    let mut names = Vec::with_capacity(recs.len());
    for (r, h) in recs.iter().zip(regs.iter()) {
        names.push(r.name.clone());
        let blob = hdr::load_body(archive.to_str().ok_or(1)?, h)?;
        let folded = alias::fold(&r.name);
        if folded == "etc/sys.conf" {
            let map = kv::pairs(&blob);
            if let Some(v) = map.get("timezone") { timezone = v.clone(); }
            if let Some(v) = map.get("cluster") { cluster = v.clone(); }
        } else if folded == "var/log/app.log" {
            for line in String::from_utf8_lossy(&blob).lines() {
                let s = line.trim();
                if !s.is_empty() { events.push(s.to_string()); }
            }
        }
    }
    events.sort(); events.dedup();
    let source = archive.file_name().and_then(|x| x.to_str()).ok_or(1)?.to_string();
    Ok(Pack { t: timezone, c: cluster, e: events, n: recs.len() as u32,
        s: source, w: digest(&names.join("\n"))? })
}
